package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;
import com.ferreteriahuaman.repository.*;
import com.ferreteriahuaman.repository.PurchaseRepository.Kind;
import com.ferreteriahuaman.dto.PurchaseModels.*;
import com.ferreteriahuaman.dto.ProductModels.ProductInput;
import com.ferreteriahuaman.dto.ProductModels.PresentationInput;
import com.ferreteriahuaman.dto.CatalogModels.StateInput;
import com.ferreteriahuaman.security.AuthModels.Identity;
import com.ferreteriahuaman.security.AuthFailure;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional
@EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class PurchaseDatabaseTest {
 @Autowired PurchaseService service;@Autowired ProductService products;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;
 Identity actor;String unique;long supplier,product,presentation;BigDecimal n(String v){return new BigDecimal(v);}
 @BeforeEach void prepare(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();String ruc="20"+String.format("%09d",Math.floorMod(UUID.randomUUID().getLeastSignificantBits(),1000000000L));supplier=service.saveSupplier(actor,"INTEGRATION_ROLLBACK",null,new SupplierInput(ruc,unique,null,null,null,null,null)).id();long cat=jdbc.queryForObject("select min(id_categoria) from huaman.categoria where estado='A'",Long.class),unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat='KGM'",Long.class);var p=products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique,"Producto de integración",null,cat,unit,true,n("0.001"),n("0.001"),"GRANEL",n("0"),null,"Kilogramo",n("20"),null));product=p.id();presentation=products.details(actor,product).presentaciones().getFirst().id();}
 DocumentInput header(Long order,String guide,UUID key){return new DocumentInput(supplier,LocalDate.now(),null,order,guide,null,null,key);}
 Details add(Kind k,Details d,String qty,String cost,Long source){return service.saveLine(actor,"INTEGRATION_ROLLBACK",k,d.documento().id(),null,new LineInput(product,presentation,n(qty),n(cost),source,k==Kind.RECEIPT?"GRANEL":null,null,d.documento().version()));}
 Details process(Kind k,Details d,UUID key){return service.process(actor,"INTEGRATION_ROLLBACK",k,d.documento().id(),new Action(key,d.documento().version(),null),false);}
 @Test void orderToPartialThenCompleteUpdatesStockAndWeightedCostExactlyOnce(){
  var order=service.save(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,null,header(null,null,UUID.randomUUID()));order=add(Kind.ORDER,order,"10","4",null);assertThat(order.documento().total()).isEqualTo("40.00");order=process(Kind.ORDER,order,UUID.randomUUID());assertThat(order.documento().estado()).isEqualTo("EMITIDA");assertThat(products.details(actor,product).producto().stockActual()).isEqualTo("0.000000");
  var receipt=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(order.documento().id(),unique+"-1",UUID.randomUUID()));receipt=add(Kind.RECEIPT,receipt,"4","4",order.lineas().getFirst().id());UUID key=UUID.randomUUID();receipt=process(Kind.RECEIPT,receipt,key);assertThat(receipt.documento().estado()).isEqualTo("CONFIRMADO");process(Kind.RECEIPT,receipt,key);assertThat(products.details(actor,product).producto().stockActual()).isEqualTo("4.000000");assertThat(service.details(Kind.ORDER,order.documento().id()).documento().estado()).isEqualTo("PARCIAL");
  var second=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(order.documento().id(),unique+"-2",UUID.randomUUID()));second=add(Kind.RECEIPT,second,"6","6",order.lineas().getFirst().id());process(Kind.RECEIPT,second,UUID.randomUUID());var p=products.details(actor,product).producto();assertThat(p.stockActual()).isEqualTo("10.000000");assertThat(p.costoPromedio()).isEqualTo("5.200000");assertThat(p.ultimoCostoCompra()).isEqualTo("6.000000");assertThat(service.details(Kind.ORDER,order.documento().id()).documento().estado()).isEqualTo("COMPLETA");assertThat(service.movements(actor,product,0,20).total()).isEqualTo(2);jdbc.execute("set constraints all immediate");
 }
 @Test void initialStockIsIdempotentAndProducesKardex(){UUID key=UUID.randomUUID();var request=new Opening(product,n("12.500"),n("4.20"),key,List.of());long first=service.opening(actor,"INTEGRATION_ROLLBACK",request).movimientoId();assertThat(service.opening(actor,"INTEGRATION_ROLLBACK",request).movimientoId()).isEqualTo(first);var p=products.details(actor,product).producto();assertThat(p.stockActual()).isEqualTo("12.500000");assertThat(p.costoPromedio()).isEqualTo("4.200000");assertThat(service.movements(actor,product,0,20).total()).isEqualTo(1);jdbc.execute("set constraints all immediate");}
 @Test void draftsCanEditLinesDeactivateAndCancelWithoutStockMovement(){var d=service.save(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,null,header(null,null,UUID.randomUUID()));d=add(Kind.ORDER,d,"5","2",null);var l=d.lineas().getFirst();d=service.saveLine(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,d.documento().id(),l.id(),new LineInput(product,presentation,n("6"),n("3"),null,null,null,d.documento().version()));assertThat(d.documento().total()).isEqualTo("18.00");d=service.lineState(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,d.documento().id(),l.id(),new StateInput("I",d.documento().version()));assertThat(d.documento().total()).isEqualTo("0.00");d=service.lineState(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,d.documento().id(),l.id(),new StateInput("A",d.documento().version()));UUID key=UUID.randomUUID();d=service.process(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,d.documento().id(),new Action(key,d.documento().version(),"Solicitud cancelada por prueba"),true);assertThat(d.documento().estado()).isEqualTo("ANULADA");assertThat(products.details(actor,product).producto().stockActual()).isEqualTo("0.000000");}
 @Test void documentCreationRetryDoesNotDuplicateDraft(){UUID key=UUID.randomUUID();var input=header(null,null,key);var first=service.save(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,null,input);var second=service.save(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,null,input);assertThat(second.documento().id()).isEqualTo(first.documento().id());assertThat(service.list(Kind.ORDER,unique,"",supplier,0,20).total()).isEqualTo(1);}
 @Test void receiptWithoutOrderAndDiscardedDraftAreSupported(){var discarded=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(null,unique+"-D",UUID.randomUUID()));discarded=service.process(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,discarded.documento().id(),new Action(UUID.randomUUID(),discarded.documento().version(),"Guía ingresada de forma incorrecta"),true);assertThat(discarded.documento().estado()).isEqualTo("ANULADO");var d=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(null,unique+"-R",UUID.randomUUID()));d=add(Kind.RECEIPT,d,"3","2",null);d=process(Kind.RECEIPT,d,UUID.randomUUID());assertThat(d.documento().total()).isEqualTo("6.00");assertThat(products.details(actor,product).producto().stockActual()).isEqualTo("3.000000");}
 @Test void rejectsOverReceiptAndStaleDraftBeforeWriting(){var order=service.save(actor,"INTEGRATION_ROLLBACK",Kind.ORDER,null,header(null,null,UUID.randomUUID()));order=add(Kind.ORDER,order,"5","2",null);order=process(Kind.ORDER,order,UUID.randomUUID());var d=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(order.documento().id(),unique+"-X",UUID.randomUUID()));var receipt=d;long source=order.lineas().getFirst().id();assertThatThrownBy(()->add(Kind.RECEIPT,receipt,"6","2",source)).isInstanceOf(AuthFailure.class);assertThatThrownBy(()->service.saveLine(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,receipt.documento().id(),null,new LineInput(product,presentation,n("1"),n("2"),source,"GRANEL",null,receipt.documento().version().minusSeconds(1)))).isInstanceOf(AuthFailure.class);}
 @Test void supplierStateAndMetadataAreAudited(){var before=service.supplier(supplier);var edited=service.saveSupplier(actor,"INTEGRATION_ROLLBACK",supplier,new SupplierInput(before.ruc(),unique+" EDITADO","Contacto","123",null,"Dirección",before.version()));assertThat(edited.razonSocial()).endsWith("EDITADO");var inactive=service.supplierState(actor,"INTEGRATION_ROLLBACK",supplier,new StateInput("I",edited.version()));assertThat(inactive.estado()).isEqualTo("I");service.supplierState(actor,"INTEGRATION_ROLLBACK",supplier,new StateInput("A",inactive.version()));assertThat(service.suppliers(unique,"A",0,20).total()).isEqualTo(1);}
 @Test void openingTracksCommercialBagsAndLooseContent(){long cat=jdbc.queryForObject("select min(id_categoria) from huaman.categoria where estado='A'",Long.class),unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat='KGM'",Long.class);var p=products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+"E","Producto por envases",null,cat,unit,true,n("0.001"),n("0.001"),"ENVASES",n("0"),null,"Kilogramo",n("20"),null));var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa 50 kg",null,n("50"),true,false,n("1"),n("1"),n("100"),null));service.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("52.5"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique+"-B","ENVASE",n("50"),bag.id()),new PhysicalUnit(unique+"-S","SUELTO",n("2.5"),null))));assertThat(service.existences(p.id(),0,20).total()).isEqualTo(2);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("52.500000");jdbc.execute("set constraints all immediate");}
 @Test void receiptCreatesIdentifiedTramosWithCorrectLength(){long cat=jdbc.queryForObject("select min(id_categoria) from huaman.categoria where estado='A'",Long.class),unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat='MTR'",Long.class);var p=products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+"T","Producto por tramos",null,cat,unit,true,n("0.001"),n("0.001"),"TRAMOS",n("0"),null,"Metro",n("20"),null));long pres=products.details(actor,p.id()).presentaciones().getFirst().id();var d=service.save(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,null,header(null,unique+"-T",UUID.randomUUID()));d=service.saveLine(actor,"INTEGRATION_ROLLBACK",Kind.RECEIPT,d.documento().id(),null,new LineInput(p.id(),pres,n("12"),n("2"),null,"TRAMO",2,d.documento().version()));process(Kind.RECEIPT,d,UUID.randomUUID());assertThat(service.existences(p.id(),0,20).total()).isEqualTo(2);assertThat(service.existences(p.id(),0,20).items()).allMatch(e->e.cantidadDisponible().equals("6.000000"));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("12.000000");jdbc.execute("set constraints all immediate");}
}
